const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');
const { FacilityManager } = require('../services/facilityManager');

const server = http.createServer();
const io = new Server(server);

const pub = new Redis(process.env.REDIS_URL);
const sub = pub.duplicate();
io.adapter(createAdapter(pub, sub));

const bldgNsp = io.of(/^\/facilities\/building-[0-9]+$/);

bldgNsp.use(async (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('Authentication required'));

  try {
    const user = jwt.verify(token, process.env.FACILITY_JWT_SECRET);
    const buildingId = socket.nsp.name.split('-')[1];

    // Enforce facility manager authorization for target building
    const canControl = await FacilityManager.checkControlPermission(user.userId, buildingId);
    if (!canControl) {
      return next(new Error('Access denied: unauthorized to manage this facility'));
    }

    socket.user = user;
    next();
  } catch {
    next(new Error('Authentication failed'));
  }
});

bldgNsp.on('connection', (socket) => {
  const buildingId = socket.nsp.name.split('-')[1];

  socket.on('actuator_override', (data) => {
    socket.nsp.emit('execute_hardware_command', {
      buildingId,
      subsystem: data.subsystem,
      state: data.state,
      issuedBy: socket.user.userId
    });
  });
});

server.listen(4007);
